SELECT * FROM ai_model_config
WHERE provider_code = #{providerCode}
  AND model_code = #{modelCode}
LIMIT 1

SELECT * FROM ai_model_config
WHERE provider_code = #{providerCode}
  AND model_code = #{modelCode}
  AND enabled = 1
LIMIT 1

SELECT COUNT(1)
FROM ai_model_config
WHERE provider_code = #{providerCode}
  AND model_code = #{modelCode}
  AND (#{id} IS NULL OR id != #{id})

